import { WindowConf } from "@droid/android";
import { useProxyWatchUpdates, useTranslation } from "@fanfanlo";
import { Box, Stack, Typography, Dialog, DialogTitle, DialogContent, DialogActions, Button } from "@mui/material";
import { useState } from "react";
import { androidFloatWindowData } from "./data";
import { useRouter } from "next/router";
import { WindowConfPreview } from "./WindowConfPreview";

// WindowConfList - 列表组件
export function WindowConfList() {
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const router = useRouter();
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleteTargetWindowId, setDeleteTargetWindowId] = useState<string | null>(null);

  const [windowList] = useProxyWatchUpdates(
    androidFloatWindowData.data.windowData,
    'windowList',
    androidFloatWindowData.data.windowData.windowList
  );

  const handleEdit = (conf: WindowConf) => {
    console.log('Edit window:', conf);
    // TODO: 实现编辑逻辑（打开编辑页面或对话框）
    router.push(`/float-window-edit?windowId=${conf.windowId}`);
  };

  const handleDeleteClick = (windowId: string) => {
    console.log('Delete window requested:', windowId);
    setDeleteTargetWindowId(windowId);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = () => {
    console.log('Delete window confirmed:', deleteTargetWindowId);
    if (deleteTargetWindowId) {
      const index = androidFloatWindowData.data.windowData.windowList.findIndex(
        w => w.windowId === deleteTargetWindowId
      );
      if (index > -1) {
        androidFloatWindowData.data.windowData.windowList.splice(index, 1);
      }
    }
    setDeleteDialogOpen(false);
    setDeleteTargetWindowId(null);
  };

  const handleDeleteCancel = () => {
    console.log('Delete window cancelled');
    setDeleteDialogOpen(false);
    setDeleteTargetWindowId(null);
  };

  return (
    <Box>
      <Stack spacing={2}>
        <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
          {t('WindowConfList.title')}
        </Typography>

        {windowList.length === 0 ? (
          <Box
            sx={{
              p: 4,
              textAlign: 'center',
              bgcolor: 'background.secondary',
              borderRadius: 1,
              border: '1px dashed',
              borderColor: 'divider'
            }}
          >
            <Typography color="text.secondary">
              {t('WindowConfList.empty')}
            </Typography>
          </Box>
        ) : (
          <Stack spacing={2}>
            {windowList.map(conf => (
              <WindowConfPreview
                key={conf.windowId}
                windowConf={conf}
                onEdit={() => handleEdit(conf)}
                onDelete={() => handleDeleteClick(conf.windowId)}
              />
            ))}
          </Stack>
        )}
      </Stack>

      <Dialog open={deleteDialogOpen} onClose={handleDeleteCancel} data-testid="WindowConfList__deleteDialog__01JG2B0025">
        <DialogTitle>{t('WindowConfList.deleteConfirmTitle')}</DialogTitle>
        <DialogContent>
          {t('WindowConfList.deleteConfirmMessage')}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleDeleteCancel} data-testid="WindowConfList__deleteCancelButton__01JG2B0026">{t('WindowConfList.deleteCancel')}</Button>
          <Button onClick={handleDeleteConfirm} color="error" variant="contained" data-testid="WindowConfList__deleteConfirmButton__01JG2B0027">
            {t('WindowConfList.deleteConfirm')}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}