import { useTranslation } from '@fanfanlo';
import { Button } from '@mui/material';
import { useRouter } from 'next/router';

export function AddWindowButton() {
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const router = useRouter();
  const handleOpen = () => {
    router.push('/float-window-add')
  };


  return (
    <>
      <Button variant="contained" color="primary" onClick={handleOpen} data-testid="AddWindowButton__addButton__01JG2B0081" data-test-comment="添加浮窗按钮，点击后导航到浮窗添加页面">
        {t('AddWindowButton.add')}
      </Button>
    </>
  );
}
